        "section": "单项选择题",
        "type": "single",
        "score": 1.0,
        "question": "李先生于一年前以每股 25 元的价格购入某上市公司股票 1000 股，持有期间获得每股现金分红 0.3 元，现以每股 30 元全部卖出。不考虑交易税费，李先生该笔投资的持有期收益率（HPR）为（ ）。",
        "options": {
          "A": "20.0%",
          "B": "21.2%",
          "C": "23.5%",
          "D": "25.0%"
        },
        "answer": "B",
        "explanation": "【持有期收益率（HPR）计算】\n① 计算公式：$HPR = \\frac{资本利得 + 红利收益}{买入本金} = \\frac{(P_1 - P_0) + D}{P_0} \\times 100\\%$\n② 代入数据：买入价 $P_0 = 25$ 元，卖出价 $P_1 = 30$ 元，每股红利 $D = 0.3$ 元\n③ 逐步推导：每股总收益 $= (30 - 25) + 0.3 = 5 + 0.3 = 5.3$ 元；$HPR = 5.3 / 25 = 0.212 = 21.2\\%$\n④ 结论对齐：该笔股票投资的持有期收益率为 21.2%，故选 B。",
        "mnemonic": "价差加上红利和，除以买入初始本。",
        "trap": "选项 A（20%）漏加了现金红利 0.3 元，只算资本利得；计算收益率必须全口径包含分红。",
